def inclusive_range(start, end):
    """Return the whole numbers from start to end, including end."""
    return list(range(start, end))

files.test_ranges.py:
import unittest

from ranges import inclusive_range


class InclusiveRangeTests(unittest.TestCase):
    def test_includes_both_ends(self):
        self.assertEqual(inclusive_range(1, 3), [1, 2, 3])

    def test_single_number(self):
        self.assertEqual(inclusive_range(5, 5), [5])


if __name__ == "__main__":
    unittest.main()

