import unittest

from durations import parse_duration


class ParseDurationTests(unittest.TestCase):
    def test_single_units(self):
        self.assertEqual(parse_duration("45s"), 45)
        self.assertEqual(parse_duration("2h"), 7200)
        self.assertEqual(parse_duration("10m"), 600)

    def test_combined_units(self):
        self.assertEqual(parse_duration("1h30m"), 5400)
        self.assertEqual(parse_duration("1h2m3s"), 3723)
        self.assertEqual(parse_duration("2h5s"), 7205)

    def test_days_and_spaces(self):
        self.assertEqual(parse_duration("1d 2h"), 93600)
        self.assertEqual(parse_duration(" 3m "), 180)

    def test_rejects_bad_text(self):
        for text in ("", "h", "5", "5x", "1m1h", "1h1h", "-5s"):
            with self.subTest(text=text), self.assertRaises(ValueError):
                parse_duration(text)


if __name__ == "__main__":
    unittest.main()
